const puppeteer = require('puppeteer');

(async () => {
  const url = 'http://localhost:3000/www/index.html';
  const browser = await puppeteer.launch({ args: ['--no-sandbox', '--disable-setuid-sandbox'] });
  const page = await browser.newPage();
  await page.goto(url, { waitUntil: 'networkidle2' });

  await page.waitForSelector('#screen');
  await page.waitForFunction(() => {
    const c = document.getElementById('screen');
    return c && c.width > 0 && c.height > 0;
  }, { timeout: 5000 });

  // helper to sample arrays in the wasm instance
  const sample = await page.evaluate(() => {
    const wasm = window.wasm || window.__wasm__; // try to access module
    // In our page we don't expose wasm globally; but wasm-bindgen default exposes to import only.
    // However we can access the memory buffer via exported functions only.
    // We'll sample via reading memory and pointers from global "wasm" variable if present.
    return 'no-access';
  });

  console.log('sample:', sample);
  await browser.close();
})();

